begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(has_column_privilege('authenticated','public.transactions','id','INSERT'),'P07: insert ID granted');
select ok(not has_column_privilege('authenticated','public.transactions','id','UPDATE'),'P12: update ID remains denied');
select ok(not has_column_privilege('authenticated','public.transactions','user_id','UPDATE'),'P12: update owner remains denied');
select ok(not has_column_privilege('authenticated','public.transactions','created_at','INSERT'),'P12: creation timestamp stays server owned');
select ok((select relrowsecurity from pg_class where oid='public.transactions'::regclass),'P12: RLS remains enabled');
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000004'),('00000000-0000-4000-8000-000000000005');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select lives_ok($$insert into public.transactions(id,kind,description,amount_cents,category_id,occurred_on) values ('40000000-0000-4000-8000-000000000004','expense','intent',3590,'expense-food','2024-02-29')$$,'P07: client operational UUID accepted');
select throws_ok($$insert into public.transactions(id,kind,description,amount_cents,category_id,occurred_on) values ('40000000-0000-4000-8000-000000000004','expense','intent',3590,'expense-food','2024-02-29')$$,'23505',null,'P07: same ID cannot duplicate');
select is((select count(*)::int from public.transactions where id='40000000-0000-4000-8000-000000000004'),1,'P07: exactly one row');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select is((select count(*)::int from public.transactions where id='40000000-0000-4000-8000-000000000004'),0,'P12: ID grant does not expose other owner');
select throws_ok($$insert into public.transactions(id,user_id,kind,description,amount_cents,category_id,occurred_on) values ('40000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000004','expense','forged',1,'expense-food','2024-02-29')$$,'42501',null,'P12: ID grant does not permit impersonation');
reset role;
select * from finish();
rollback;
